import { client } from 'puppeteer';
const browser = await client();
const page = await browser.newPage();
const link = 'https://translate.google.com';
await page.goto(link);
await page.waitFor(1000);
const element = await page.$eval('input[name="q"]', e => e.value);
page.keyboard.type(element, 'Hello');
await page.waitFor(2000);
const data = await page.evaluate(() => document.querySelector('p').innerText);
await browser.close();
console.log(data);
